<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { api, ApiError, basePath, online, principal } from '../api'
import { categories, fieldNames, type InputError } from '../inputFields'
type Row = Record<string, string | number | boolean | null>
type Bundle = Record<string, unknown>
interface Preview { valid: boolean; errors: InputError[]; payload?: Bundle; plan?: {segments: Row[]}; evaluation?: {executable:boolean;weekly_results:Row[]}; demands?: Row[] }
const editor=computed(()=>principal.value?.roles.includes('editor'))
const mode=ref('initialization'), busy=ref(false), error=ref(''), notice=ref('')
const head=ref({revision:0,input_version:0,latest_adoption:0}), result=ref<Preview|null>(null)
const files=ref<Array<{file_id:string;attribution_date:string;version:number;effective:boolean;rows:Row[]}>>([])
const kind=ref('segments'), paste=ref(''), attribution=ref(''), complete=ref(false), cutoff=ref('')
const schemas:Record<string,string[]>={segments:['id','date','line_code','order','model_code','quantity'],demands:['model_code','week','week_label','quantity'],coverage:['start_date','end_date','line_codes','model_codes','blanks_are_zero'],reset:['batch_id','production_week','cutoff','model_code','wip','net_balance'],execution_facts:['date','line_code','model_code','quantity'],execution_coverage:['start_date','end_date','line_codes','model_codes','blanks_are_zero'],initial_states:['line_code','recipe_code'],...Object.fromEntries(categories.map(c=>[c.kind,c.fields]))}
const titles:Record<string,string>={segments:'现行计划生产段',demands:'完整十五周需求',coverage:'旧计划覆盖范围',reset:'外部周一快照',execution_facts:'累计执行事实',execution_coverage:'已确认执行事实范围',initial_states:'线体起始 Recipe',...Object.fromEntries(categories.map(c=>[c.kind,c.title]))}
const labels:Record<string,string>={...fieldNames,id:'段编号',quantity:'数量 (片)',order:'人工日内顺序',week_label:'周别',start_date:'覆盖起日',end_date:'覆盖终日',line_codes:'线体编码列表 (以 | 分隔)',model_codes:'机种编码列表 (以 | 分隔)',blanks_are_zero:'覆盖内空白为零 (true/false)',production_week:'所属周周一',cutoff:'周一08:00截止时点 (含时区)',wip:'在制品 (片)',net_balance:'净余额 (可为负)',delta:'需求增减 (有符号整数片)'}
const tables=ref<Record<string,Row[]>>(Object.fromEntries(Object.keys(schemas).map(k=>[k,[]])))
const demandRows=ref<Row[]>([])
const columns=computed(()=>mode.value==='demands'?['model_code','week','week_label','delta']:schemas[kind.value]??[])
const rows=computed(()=>mode.value==='demands'?demandRows.value:tables.value[kind.value]??[])
const outstanding=ref<{operation_id:string;mode:string}|null>(null)
const storageWarning=ref('')
const storageKey=computed(()=>`auto-plan-import-pending:${basePath}:${principal.value?.user_id}`)
function remember(value:typeof outstanding.value){outstanding.value=value;try{if(value)localStorage.setItem(storageKey.value,JSON.stringify(value));else localStorage.removeItem(storageKey.value)}catch{storageWarning.value='浏览器无法保存核实编号。仍可提交到服务器；结果未知时请保留此页并核实，刷新后将无法自动恢复编号。'}}
function changed(){result.value=null;notice.value=''}
async function load(){head.value=await api('/plans/current');if(head.value.revision) files.value=(await api<{files:typeof files.value}>('/demands/files')).files}
onMounted(async()=>{try{const saved=localStorage.getItem(storageKey.value);if(saved){const value=JSON.parse(saved);if(typeof value.operation_id==='string'&&['initialization','demands'].includes(value.mode))outstanding.value={operation_id:value.operation_id,mode:value.mode}}}catch{storageWarning.value='浏览器无法读取本地核实编号。请保留当前页面完成提交和核实。'}try{await load()}catch(e){error.value=e instanceof Error?e.message:'读取失败'}})
function add(){rows.value.push(Object.fromEntries(columns.value.map(k=>[k,''])));changed()}
function tableText(name:string,entries:Row[]){return [schemas[name]!.join('\t'),...entries.map(r=>schemas[name]!.map(k=>String(r[k]??'')).join('\t'))].join('\n')}
function errorMessage(e:unknown){error.value=e instanceof Error?e.message:'操作失败';if(e instanceof ApiError&&Array.isArray(e.data.errors))result.value={valid:false,errors:e.data.errors as InputError[]}}
async function preview(){busy.value=true;error.value='';notice.value='';try{
 if(mode.value==='demands') result.value=await api('/demands/preview',{method:'POST',body:JSON.stringify({input_version:head.value.input_version,attribution_date:attribution.value||null,rows:demandRows.value})})
 else {const texts=Object.fromEntries(Object.keys(schemas).map(k=>[k,tableText(k,tables.value[k]??[])]));texts.settings=`complete_weekly_demands\texecution_cutoff\n${complete.value}\t${cutoff.value}`;result.value=await api('/initialization/paste/preview',{method:'POST',body:JSON.stringify({base_revision:head.value.revision,input_version:head.value.input_version,latest_adoption:head.value.latest_adoption,tables:texts})})}
 }catch(e){errorMessage(e)}finally{busy.value=false}}
async function previewPaste(){busy.value=true;error.value='';try{if(mode.value==='demands')result.value=await api('/demands/paste/preview',{method:'POST',body:JSON.stringify({input_version:head.value.input_version,attribution_date:attribution.value||null,text:paste.value})});else{const lines=paste.value.trimEnd().split('\n');const headers=lines.shift()?.split('\t')??[];if(headers.join('\t')!==schemas[kind.value]!.join('\t'))throw new Error('首行列名须与当前表格模板一致');tables.value[kind.value]=lines.filter(Boolean).map(line=>Object.fromEntries(line.split('\t').map((v,i)=>[headers[i]!,v])));changed();await preview()}}catch(e){errorMessage(e)}finally{busy.value=false}}
async function upload(event:Event){const file=(event.target as HTMLInputElement).files?.[0];if(!file)return;busy.value=true;error.value='';try{const query=mode.value==='demands'?`input_version=${head.value.input_version}${attribution.value?`&attribution_date=${attribution.value}`:''}`:`base_revision=${head.value.revision}&input_version=${head.value.input_version}&latest_adoption=${head.value.latest_adoption}`;result.value=await api(`/${mode.value}/excel/preview?${query}`,{method:'POST',headers:{'Content-Type':'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'},body:file})}catch(e){errorMessage(e)}finally{busy.value=false}}
async function apply(){if(!result.value?.valid)return;busy.value=true;error.value='';try{const payload=result.value.payload??{input_version:head.value.input_version,attribution_date:attribution.value||null,rows:demandRows.value};const operation={operation_id:crypto.randomUUID(),mode:mode.value};remember(operation);await api(`/${mode.value}/apply`,{method:'POST',body:JSON.stringify({...payload,operation_id:operation.operation_id})});remember(null);notice.value=mode.value==='initialization'?'首次接入已保存为待处理共享草稿。请在共享计划中检查后明确采用。':'整日需求文件已替换，旧版本保留。';result.value=null;await load()}catch(e){errorMessage(e);if(e instanceof ApiError&&((e.status>=400&&e.status<500&&e.status!==408)||e.data.state==='busy'))remember(null)}finally{busy.value=false}}
async function verify(){if(!outstanding.value)return;busy.value=true;try{const pending=outstanding.value;const answer=await api<{status:string}>(pending.mode==='initialization'?'/plans/verify':'/demands/verify',{method:'POST',body:JSON.stringify({operation_id:pending.operation_id})});notice.value=answer.status==='COMMITTED'?'前次导入已提交，已重新读取。':'前次导入已作废，可重新预览后提交。';remember(null);await load()}catch(e){errorMessage(e)}finally{busy.value=false}}
</script>
<template>
<section><h1>首次接入与需求变更</h1>
<p>生产日以北京时间08:00分界，需求周从周一08:00开始，共十五周。需求文件归属日期以北京时间00:00分界。</p>
<el-alert v-if="storageWarning" :title="storageWarning" type="warning" :closable="false"/><el-alert v-if="error" :title="error" type="error" :closable="false"/><el-alert v-if="notice" :title="notice" type="success" :closable="false"/>
<el-alert v-if="outstanding" title="前次导入结果待核实，当前只读。核实完成后才能继续提交。" type="warning" :closable="false"/><el-button v-if="outstanding" @click="verify" :disabled="busy||!online">核实前次导入</el-button>
<el-radio-group v-model="mode" @change="changed"><el-radio-button value="initialization">首次接入</el-radio-button><el-radio-button value="demands">按日需求变更</el-radio-button></el-radio-group>
<div v-if="mode==='initialization'"><p>现行计划已在外部完成本周重置，导入后保持原数量。本周不再次抵扣净余额，也不能更正本周重置。须提供完整十五周需求，包含已满足部分。旧计划覆盖内空白是否为零必须明确。</p><el-alert v-if="head.revision" title="已有共享计划，首次接入已关闭。后续请维护输入资料或导入需求变更。" type="info" :closable="false"/></div>
<div v-else><p>同日新文件整份替换旧文件贡献，省略旧行即撤回。重复内容的独立行分别计入。历史修订会重放后来日期，每一步不得负数。</p><label>变更归属日期 <el-input v-model="attribution" placeholder="YYYY-MM-DD，留空为北京今天" @input="changed"/></label></div>
<fieldset :disabled="!editor||busy||!online||!!outstanding||(mode==='initialization'&&head.revision>0)">
<p><a :href="`${basePath}/api/${mode}/template.xlsx`">下载标准 Excel 模板</a> <label>上传标准工作簿并预览 <input type="file" accept=".xlsx" @change="upload" /></label></p>
<template v-if="mode==='initialization'"><label>编辑资料类别 <el-select v-model="kind"><el-option v-for="(title,key) in titles" :key="key" :label="title" :value="key"/></el-select></label><p>编码须与主资料一致。可先在输入资料维护主资料，也可在同一初始化模板中一起填写。</p><el-checkbox v-model="complete" @change="changed">确认完整整周需求包含已满足部分，零需求已显式填写</el-checkbox><label>已确认执行事实截止时点 <el-input v-model="cutoff" placeholder="2026-10-14T08:00:00+08:00" @input="changed"/></label></template>
<el-button @click="add">添加一行</el-button>
<div class="table-scroll"><table><thead><tr><th v-for="column in columns" :key="column">{{labels[column]??column}}</th><th>操作</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="index"><td v-for="column in columns" :key="column"><input v-model="row[column]" :aria-label="`${labels[column]??column} 第${index+1}行`" @input="changed"/></td><td><el-button @click="rows.splice(index,1);changed()">移除此行</el-button></td></tr></tbody></table></div>
<p>粘贴带标准列名的制表符表格：</p><el-input v-model="paste" type="textarea" :rows="4"/><el-button @click="previewPaste">读取粘贴并预览</el-button><el-button @click="preview">预览全部资料</el-button><el-button type="primary" :disabled="!result?.valid" @click="apply">{{mode==='initialization'?'确认导入待处理草稿':'确认替换整日需求文件'}}</el-button>
</fieldset>
<div v-if="result"><p role="status">{{result.valid?'预览通过，尚未写入。':'预览未通过，原资料保持。'}}</p><el-table v-if="result.errors.length" :data="result.errors"><el-table-column prop="sheet" label="工作表"/><el-table-column prop="row" label="行"/><el-table-column prop="field" label="字段"/><el-table-column prop="reason" label="原因"/></el-table><p v-if="result.plan&&mode==='initialization'">导入生产段 {{result.plan.segments.length}} 段。服务器已生成精确工时证书。{{result.evaluation?.executable?'规则核算可执行。':'仍有待处理事项，导入后检查共享草稿。'}}</p><el-table v-if="mode==='demands'&&result.evaluation" :data="result.evaluation.weekly_results"><el-table-column prop="model_code" label="机种"/><el-table-column prop="week" label="需求周周一"/><el-table-column prop="demand" label="完整需求"/><el-table-column prop="gap" label="未补足缺口"/><el-table-column prop="on_time_rate_display" label="按时满足率"/></el-table><el-table v-if="result.demands" :data="result.demands"><el-table-column prop="model_code" label="机种"/><el-table-column prop="week" label="需求周周一"/><el-table-column prop="quantity" label="完整需求片数"/></el-table></div>
<details v-if="files.length"><summary>需求文件版本和独立行</summary><div v-for="file in files" :key="file.file_id"><h3>{{file.attribution_date}} 第{{file.version}}版 {{file.effective?'当前有效':'已被替换'}}</h3><el-table :data="file.rows"><el-table-column prop="row_id" label="独立行编号"/><el-table-column prop="model_code" label="机种"/><el-table-column prop="week" label="需求周"/><el-table-column prop="delta" label="增减片数"/></el-table></div></details>
</section>
</template>
<style scoped>fieldset{border:0;padding:1rem 0}label{display:block;margin:1rem 0}.table-scroll{overflow:auto}th,td{padding:.4rem}td input{width:150px;min-height:30px}a{margin-right:1rem}</style>
